/bin/bash -lc "cat > /workspace/openai_client.py <<'EOF'
\"\"\"Minimal OpenAI Responses API client using only the standard library.

The API key is read from the OPENAI_API_KEY environment variable (or passed
explicitly). Prompts are sent with "'``store=False`` so OpenAI does not retain
the response, and nothing is logged or written to disk by this module.
"""

import json
import os
import sys
import urllib.error
import urllib.request

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o-mini"


class OpenAIError(Exception):
    """Raised when the API returns an error or an unexpected response."""


class OpenAIClient:
    def __init__(self, api_key=None, model=DEFAULT_MODEL, base_url=API_URL, timeout=60):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("Set OPENAI_API_KEY or pass api_key.")
        self.model = model
        self.base_url = base_url
        self.timeout = timeout

    def create_response(self, prompt, model=None, instructions=None, store=False, **params):
        """Send a text prompt and return the full parsed JSON response."""
        payload = {"model": model or self.model, "input": prompt, "store": store}
        if instructions:
            payload["instructions"] = instructions
        payload.update(params)

        request = urllib.request.Request(
            self.base_url,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": "Bearer " + self.api_key,
                "Content-Type": "application/json",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as error:
            detail = error.read().decode("utf-8", errors="replace")
            try:
                detail = json.loads(detail)["error"]["message"]
            except (ValueError, KeyError, TypeError):
                pass
            raise OpenAIError("HTTP %d: %s" % (error.code, detail)) from None
        except urllib.error.URLError as error:
            raise OpenAIError("Connection failed: %s" % error.reason) from None

    @staticmethod
    def extract_text(response):
        """Concatenate the output text from a Responses API result."""
        parts = []
        for item in response.get("output", []):
            if item.get("type") != "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
        return "".join(parts)

    def ask(self, prompt, **kwargs):
        """Send a prompt and return just the reply text."""
        return self.extract_text(self.create_response(prompt, **kwargs))


def ask(prompt, **kwargs):
    """Convenience wrapper: one prompt in, reply text out."""
    return OpenAIClient().ask(prompt, **kwargs)


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    prompt = " ".join(args) if args else sys.stdin.read()
    if not prompt.strip():
        print("Usage: openai_client.py PROMPT  (or pipe the prompt on stdin)", file=sys.stderr)
        return 2
    try:
        print(ask(prompt))
    except OpenAIError as error:
        print("Error: %s" % error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
